SELECT
  json_extract(value, '$.concept') AS "concept",
  json_extract(value, '$.chat') AS "chat",
  json_extract(value, '$.messages') AS "messages",
  json_extract(value, '$.responses') AS "responses"
FROM json_each('[{"concept": "Assistant tool request", "chat": "tool_calls; function.arguments is JSON encoded as a string", "messages": "content block: tool_use; input is a JSON object", "responses": "function_call item; arguments and call_id"}, {"concept": "Completion text", "chat": "choices[].message.content", "messages": "Text blocks within content[]", "responses": "Output message items containing text blocks"}, {"concept": "Generation limit", "chat": "max_tokens or max_completion_tokens, selected by model/profile", "messages": "max_tokens; thinking budget must fit", "responses": "max_output_tokens, with model-specific semantics"}, {"concept": "Instructions", "chat": "system message in messages[] in this adapter", "messages": "Top-level system in this adapter", "responses": "instructions and/or supported input message roles"}, {"concept": "Stop / finish", "chat": "finish_reason: stop, tool_calls, length, etc.", "messages": "stop_reason: end_turn, tool_use, max_tokens, etc.", "responses": "Response status and incomplete details; inspect output items"}, {"concept": "Stream framing", "chat": "SSE choice deltas; assemble text and tool arguments", "messages": "SSE message/content-block events and deltas", "responses": "SSE response/item/content events"}, {"concept": "Tool definition", "chat": "tools[].function.parameters", "messages": "tools[].input_schema", "responses": "Function tool schema in the Responses tools list"}, {"concept": "Tool result", "chat": "role: tool with tool_call_id", "messages": "user content block: tool_result with tool_use_id", "responses": "function_call_output item with call_id"}, {"concept": "Usage", "chat": "prompt_tokens / completion_tokens; optional details", "messages": "input_tokens / output_tokens and cache fields", "responses": "input_tokens / output_tokens and API-specific details"}]');
